#include "FirewallTx_FirewallTx.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void FirewallTx_FirewallTx_initialize(void);
void FirewallTx_FirewallTx_notify(microkit_channel channel);
void FirewallTx_FirewallTx_timeTriggered(void);

volatile sb_queue_SW_StructuredEthernetMessage_i_1_t *EthernetFramesTxIn_queue_1;
sb_queue_SW_StructuredEthernetMessage_i_1_Recv_t EthernetFramesTxIn_recv_queue;
volatile sb_queue_SW_StructuredEthernetMessage_i_1_t *EthernetFramesTxOut_queue_1;
volatile sb_queue_SW_AttackStatus_1_t *AttackStatusTx_queue_1;
volatile sb_queue_SW_Mode_1_t *CurrentMode_queue_1;
sb_queue_SW_Mode_1_Recv_t CurrentMode_recv_queue;

#define PORT_FROM_MON 0

bool EthernetFramesTxIn_is_empty(void) {
  return sb_queue_SW_StructuredEthernetMessage_i_1_is_empty(&EthernetFramesTxIn_recv_queue);
}

bool get_EthernetFramesTxIn_poll(sb_event_counter_t *numDropped, SW_StructuredEthernetMessage_i *data) {
  return sb_queue_SW_StructuredEthernetMessage_i_1_dequeue((sb_queue_SW_StructuredEthernetMessage_i_1_Recv_t *) &EthernetFramesTxIn_recv_queue, numDropped, data);
}

bool get_EthernetFramesTxIn(SW_StructuredEthernetMessage_i *data) {
  sb_event_counter_t numDropped;
  return get_EthernetFramesTxIn_poll (&numDropped, data);
}

uintmax_t get_EthernetFramesTxIn_num_invalid(void) {
  return sb_queue_SW_StructuredEthernetMessage_i_1_numInvalid((sb_queue_SW_StructuredEthernetMessage_i_1_Recv_t *) &EthernetFramesTxIn_recv_queue);
}

bool put_EthernetFramesTxOut(const SW_StructuredEthernetMessage_i *data) {
  sb_queue_SW_StructuredEthernetMessage_i_1_enqueue((sb_queue_SW_StructuredEthernetMessage_i_1_t *) EthernetFramesTxOut_queue_1, (SW_StructuredEthernetMessage_i *) data);

  return true;
}

bool put_AttackStatusTx(const SW_AttackStatus *data) {
  sb_queue_SW_AttackStatus_1_enqueue((sb_queue_SW_AttackStatus_1_t *) AttackStatusTx_queue_1, (SW_AttackStatus *) data);

  return true;
}

SW_Mode last_CurrentMode_payload;

bool get_CurrentMode(SW_Mode *data) {
  sb_event_counter_t numDropped;
  SW_Mode fresh_data;
  bool isFresh = sb_queue_SW_Mode_1_dequeue((sb_queue_SW_Mode_1_Recv_t *) &CurrentMode_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_CurrentMode_payload = fresh_data;
  }
  *data = last_CurrentMode_payload;
  return isFresh;
}

uintmax_t get_CurrentMode_num_invalid(void) {
  return sb_queue_SW_Mode_1_numInvalid((sb_queue_SW_Mode_1_Recv_t *) &CurrentMode_recv_queue);
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_SW_StructuredEthernetMessage_i_1_Recv_init(&EthernetFramesTxIn_recv_queue, (sb_queue_SW_StructuredEthernetMessage_i_1_t *) EthernetFramesTxIn_queue_1);

  sb_queue_SW_StructuredEthernetMessage_i_1_init((sb_queue_SW_StructuredEthernetMessage_i_1_t *) EthernetFramesTxOut_queue_1);

  sb_queue_SW_AttackStatus_1_init((sb_queue_SW_AttackStatus_1_t *) AttackStatusTx_queue_1);

  sb_queue_SW_Mode_1_Recv_init(&CurrentMode_recv_queue, (sb_queue_SW_Mode_1_t *) CurrentMode_queue_1);

  FirewallTx_FirewallTx_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      FirewallTx_FirewallTx_timeTriggered();
      // Report that this dispatch has finished.  The _MON wrapper forwards it to
      // the scheduler.  The default scheduler ignores runtime signals from
      // partitions -- the schedule is static and each partition runs for its full
      // allotted time -- so this is inert there; the test scheduler uses it as the
      // slot-complete event, which is what lets it step as fast as threads run
      // rather than waiting out each slot's wall-clock budget.
      microkit_notify(PORT_FROM_MON);
      break;
    default:
      FirewallTx_FirewallTx_notify(channel);
  }
}
